// LeetCode 528 — pick index i with probability w[i] / (sum of w).
public sealed class WeightedPicker {
    private readonly long[] _prefix;       // _prefix[i] = w[0] + ... + w[i]; long, so big weights cannot overflow
    private readonly Random _rnd;

    public WeightedPicker(int[] w) : this(w, new Random()) { }
    public WeightedPicker(int[] w, Random rnd) {
        if (w == null || w.Length == 0) throw new ArgumentException("no weights");
        _prefix = new long[w.Length];
        long sum = 0;
        for (int i = 0; i < w.Length; i++) {
            if (w[i] < 0) throw new ArgumentException("negative weight");
            sum += w[i];
            _prefix[i] = sum;
        }
        if (sum == 0) throw new ArgumentException("all weights are zero");
        _rnd = rnd;
    }

    public int PickIndex() {
        long r = _rnd.NextInt64(_prefix[_prefix.Length - 1]);   // a random point in [0, total)
        // The first index whose running total is greater than r owns that point. Binary search: O(log n).
        int lo = 0, hi = _prefix.Length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (_prefix[mid] > r) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}
